const e={version:"2026-10-01",sections:[{id:"A",en:"A. Purpose & Scope",ar:"أ. الغرض والنطاق"},{id:"B",en:"B. Photos",ar:"ب. الصور"},{id:"C",en:"C. Ratings & Notes",ar:"ج. التقييمات والملاحظات"},{id:"D",en:"D. Report Record",ar:"د. سجل التقرير"},{id:"E",en:"E. Parties, Tenancy & Signatures",ar:"هـ. الأطراف وعقد الإيجار والتوقيعات"},{id:"F",en:"F. Personal Data & Service Provider",ar:"و. البيانات الشخصية ومزوّد الخدمة"}],en:{heading:"Report Scope & Method",declarationHeading:"Legal Declaration",unsigned:"Not signed at inspection",clauses:[["A1","This report records the visible condition of the property at the date and time of inspection shown in the report."],["A2","This is not a snagging report, structural survey, engineering report, valuation or legal opinion."],["A3","It does not assess build quality or hidden or latent defects."],["A4","It does not decide who is responsible for any condition, damage or cost, or whether anything is normal wear and tear."],["A5","Furniture and belongings were not moved. Locked, concealed or inaccessible areas and items were not inspected, unless stated otherwise."],["A6","The inspection is visual and non-invasive. Appliances, fittings and systems were not tested for function, safety or reliability, unless stated otherwise."],["A7","Items that are not listed in this report were not assessed."],["B1","Photos were taken by the inspector using the MeInspect app during the inspection. Each photo shows the date and time it was captured."],["B2","Photos show only what is visible in the frame, and colours or brightness may differ from the real condition."],["B3","Photos are resized and compressed to keep the report file at a practical size."],["C1","Ratings are the inspector's visual assessment on the day, using the rating scale shown in this report. A rating is not a measurement and not a finding about cause or responsibility."],["C2","Notes and descriptions are entered by the inspector. MeInspect does not verify them."],["D1","Each report has a unique report ID and a generation date and time. The location (GPS) and IP address shown in the page footer were recorded by the app."],["E1","Property, party and tenancy details (including contract number and dates) were entered into the app. MeInspect has not verified them against any official record."],["E2","Signatures were captured electronically in the app at the date and time shown."],["E3","By signing, a person confirms that they have reviewed this report and that, to the best of their knowledge, it reflects the condition of the property on the inspection date. Signing does not waive any right under the tenancy contract or the law. This report is not a tenancy contract and does not amend it."],["E4","A party who did not sign has not confirmed this report. We recommend that such a party raises any disagreement in writing with the other parties within 7 days of receiving it. Not doing so does not by itself mean that the party accepts the report or affect any of their rights."],["F1","This report contains personal data of the parties named in it, such as names, phone numbers, email addresses and signatures. Please store and share it carefully and only as needed."],["F2","MeInspect provides the app used to prepare this report. It does not verify the observations recorded in it."]],declaration:"By digitally signing below, all signing parties confirm they have reviewed the complete MeInspect Property Condition Report and agree that, to the best of their knowledge, it reflects the condition of the property on the inspection date. Signing does not waive any right under the tenancy contract or the law."},ar:{heading:"نطاق التقرير ومنهجيته",declarationHeading:"إقرار",unsigned:"لم يوقّع وقت الفحص",clauses:[["A1","يسجّل هذا التقرير الحالة المرئية للعقار في تاريخ ووقت الفحص المبيّنين فيه."],["A2","هذا التقرير ليس تقرير عيوب بناء ولا مسحاً إنشائياً ولا تقريراً هندسياً ولا تقييماً سعرياً ولا رأياً قانونياً."],["A3","لا يقيّم هذا التقرير جودة البناء ولا العيوب المخفية أو الكامنة."],["A4","لا يحدد هذا التقرير الطرف المسؤول عن أي حالة أو ضرر أو تكلفة، ولا ما إذا كان أي أمر يُعدّ استهلاكاً عادياً."],["A5","لم يتم تحريك الأثاث أو الأغراض. ولم تُفحص المناطق والعناصر المغلقة أو المخفية أو التي يتعذّر الوصول إليها، ما لم يُذكر خلاف ذلك."],["A6","الفحص بصري وغير تدخّلي. ولم تُختبر الأجهزة والتجهيزات والأنظمة من حيث التشغيل أو السلامة أو الموثوقية، ما لم يُذكر خلاف ذلك."],["A7","العناصر غير المدرجة في هذا التقرير لم يتم تقييمها."],["B1","التقط المفتّش الصور باستخدام تطبيق MeInspect أثناء الفحص، وتُظهر كل صورة تاريخ ووقت التقاطها."],["B2","تُظهر الصور ما هو مرئي في إطارها فقط، وقد تختلف الألوان أو الإضاءة عن الواقع."],["B3","يتم تغيير حجم الصور وضغطها للحفاظ على حجم عملي لملف التقرير."],["C1","التقييمات هي تقدير المفتّش البصري في يوم الفحص وفق مقياس التقييم المبيّن في هذا التقرير. والتقييم ليس قياساً ولا حكماً بشأن السبب أو المسؤولية."],["C2","يُدخل المفتّش الملاحظات والأوصاف، ولا تتحقق MeInspect من صحتها."],["D1","لكل تقرير رقم تعريف فريد وتاريخ ووقت إنشاء. ويظهر في تذييل الصفحة الموقع (GPS) وعنوان IP اللذان سجّلهما التطبيق."],["E1","أُدخلت بيانات العقار والأطراف وعقد الإيجار (بما في ذلك رقم العقد وتواريخه) في التطبيق، ولم تتحقق MeInspect منها مقابل أي سجل رسمي."],["E2","جرى التقاط التوقيعات إلكترونياً داخل التطبيق في التاريخ والوقت المبيّنين."],["E3","بالتوقيع، يؤكد الشخص أنه اطّلع على هذا التقرير وأنه، بحسب علمه، يعكس حالة العقار في تاريخ الفحص. ولا يُعدّ التوقيع تنازلاً عن أي حق بموجب عقد الإيجار أو القانون. وهذا التقرير ليس عقد إيجار ولا يعدّله."],["E4","الطرف الذي لم يوقّع لم يؤكد هذا التقرير. ونوصي هذا الطرف بإبلاغ الأطراف الأخرى كتابةً بأي اعتراض خلال 7 أيام من استلام التقرير. وعدم القيام بذلك لا يعني بحد ذاته قبول التقرير ولا يؤثر في أي من حقوقه."],["F1","يتضمن هذا التقرير بيانات شخصية للأطراف المذكورة فيه، مثل الأسماء وأرقام الهاتف والبريد الإلكتروني والتوقيعات. يُرجى حفظه ومشاركته بعناية وبالقدر اللازم فقط."],["F2","توفّر MeInspect التطبيق المستخدم في إعداد هذا التقرير، ولا تتحقق من صحة الملاحظات المسجّلة فيه."]],declaration:"بالتوقيع الرقمي أدناه، يؤكد الأطراف الموقّعون أنهم اطّلعوا على تقرير حالة العقار الكامل من MeInspect، ويوافقون على أنه، بحسب علمهم، يعكس حالة العقار في تاريخ الفحص. ولا يُعدّ التوقيع تنازلاً عن أي حق بموجب عقد الإيجار أو القانون."}},t={very_good:{ar:"جيد جداً",en:"No visible deterioration noted.",definitionAr:"لم يُلاحظ تدهور ظاهر.",color:"#059669",background:"#ecfdf5"},good:{ar:"جيد",en:"Minor visible signs of use noted.",definitionAr:"لوحظت آثار استخدام طفيفة ظاهرة.",color:"#16a34a",background:"#f0fdf4"},fair:{ar:"متوسط",en:"Visible wear or deterioration noted.",definitionAr:"لوحظ استهلاك أو تدهور ظاهر.",color:"#b45309",background:"#fffbeb"},poor:{ar:"مشكلة",en:"A visible condition issue noted.",definitionAr:"لوحظت مشكلة ظاهرة في الحالة.",color:"#b91c1c",background:"#fef2f2"}};export{t as a,e as r};
